package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.ArrayBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.BindingSetOrigin;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class NativeBindingDomainNoWriteOverlayTest {
	private static final Value OLD = SimpleValueFactory.getInstance().createIRI("urn:no-write:old");
	private static final Value NEW = SimpleValueFactory.getInstance().createIRI("urn:no-write:new");

	@Test
	void trackedEmptyQuerySourceDoesNotTrackAnUnchangedTarget() {
		QueryBindingSet target = new QueryBindingSet();
		target.setBinding("payload", OLD);
		assertFalse(BindingSetOrigin.isTrackedInput(target));

		BindingSet source = BindingSetOrigin.optimizationInput(request("sourceOnly", NEW));
		assertTrue(BindingSetOrigin.isTrackedInput(source));
		assertTrue(source.getBindingNames().isEmpty(), "the source has retained authority but no mapping write");
		assertSame(NEW, BindingSetOrigin.of(source).parameterValue("sourceOnly"));

		target.addAll(source);

		BindingSet reentered = BindingSetOrigin.requestInput(target);
		assertAll(
				() -> assertEquals(Set.of("payload"), target.getBindingNames()),
				() -> assertSame(OLD, target.getValue("payload")),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(target),
						"an empty accepted-write set must not turn an untracked target into tracked UNKNOWN"),
				() -> assertTrue(BindingSetOrigin.of(reentered).isRequest("payload"),
						"a later real request entry must still recognize the unchanged mapping"));
	}

	@Test
	void emptyQueryOverlayPreservesTheExistingTrackedTargetOrigin() {
		QueryBindingSet target = new QueryBindingSet(BindingSetOrigin.requestInput(request("payload", OLD)));
		BindingSetOrigin before = BindingSetOrigin.of(target);
		BindingSet source = BindingSetOrigin.optimizationInput(request("sourceOnly", NEW));

		target.addAll(source);

		assertAll(
				() -> assertSame(before, BindingSetOrigin.of(target),
						"no accepted source mapping means no provenance overlay"),
				() -> assertSame(OLD, target.getValue("payload")),
				() -> assertTrue(BindingSetOrigin.of(target).isRequest("payload")));
	}

	@Test
	void acceptedQueryMappingStillTransfersItsRequestOrigin() {
		QueryBindingSet target = new QueryBindingSet();
		target.setBinding("payload", OLD);
		BindingSet source = BindingSetOrigin.requestInput(request("payload", NEW));

		target.addAll(source);

		assertAll(
				() -> assertSame(NEW, target.getValue("payload")),
				() -> assertTrue(BindingSetOrigin.isTrackedInput(target)),
				() -> assertTrue(BindingSetOrigin.of(target).isRequest("payload")));
	}

	@Test
	void rejectedArraySchemaWritesDoNotTrackAnUnchangedTarget() {
		ArrayBindingSet target = new ArrayBindingSet("payload");
		target.setBinding("payload", OLD);
		assertFalse(BindingSetOrigin.isTrackedInput(target));

		ArrayBindingSet source = new ArrayBindingSet("outside");
		source.setBinding("outside", NEW);
		BindingSetOrigin.set(source, BindingSetOrigin.of(BindingSetOrigin.requestInput(source)));
		assertTrue(BindingSetOrigin.isTrackedInput(source));
		assertEquals(Set.of("outside"), source.getBindingNames());

		target.addAll(source);

		BindingSet reentered = BindingSetOrigin.requestInput(target);
		assertAll(
				() -> assertSame(OLD, target.getValue("payload")),
				() -> assertEquals(Set.of("payload"), target.getBindingNames()),
				() -> assertFalse(BindingSetOrigin.isTrackedInput(target),
						"source names outside the fixed target schema are not accepted writes"),
				() -> assertTrue(BindingSetOrigin.of(reentered).isRequest("payload"),
						"schema rejection must not disable a later real request entry"));
	}

	@Test
	void rejectedArraySchemaWritesPreserveTheTrackedTargetOrigin() {
		ArrayBindingSet target = new ArrayBindingSet("payload");
		target.setBinding("payload", OLD);
		BindingSetOrigin.set(target, BindingSetOrigin.of(BindingSetOrigin.requestInput(target)));
		BindingSetOrigin before = BindingSetOrigin.of(target);
		ArrayBindingSet source = new ArrayBindingSet("outside");
		source.setBinding("outside", NEW);
		BindingSetOrigin.set(source, BindingSetOrigin.of(BindingSetOrigin.requestInput(source)));

		target.addAll(source);

		assertAll(
				() -> assertSame(before, BindingSetOrigin.of(target),
						"unaccepted schema names cannot add source authority"),
				() -> assertSame(OLD, target.getValue("payload")),
				() -> assertTrue(BindingSetOrigin.of(target).isRequest("payload")),
				() -> assertFalse(BindingSetOrigin.of(target).isRequest("outside")));
	}

	@Test
	void acceptedArrayMappingStillTransfersItsRequestOrigin() {
		ArrayBindingSet target = new ArrayBindingSet("payload");
		target.setBinding("payload", OLD);
		ArrayBindingSet source = new ArrayBindingSet("payload");
		source.setBinding("payload", NEW);
		BindingSetOrigin.set(source, BindingSetOrigin.of(BindingSetOrigin.requestInput(source)));

		target.addAll(source);

		assertAll(
				() -> assertSame(NEW, target.getValue("payload")),
				() -> assertTrue(BindingSetOrigin.isTrackedInput(target)),
				() -> assertTrue(BindingSetOrigin.of(target).isRequest("payload")));
	}

	private static MapBindingSet request(String name, Value value) {
		MapBindingSet request = new MapBindingSet();
		request.addBinding(name, value);
		return request;
	}
}
